set-variable.value:
@{
    try {
      if (!context.Variables.ContainsKey("byokCallerAuthenticated") || !(bool)context.Variables["byokCallerAuthenticated"]
          || !context.Variables.ContainsKey("byokResponseOwnerMarker")) { return ""; }
      var marker = (string)context.Variables["byokResponseOwnerMarker"];
      if (!System.Text.RegularExpressions.Regex.IsMatch(marker, @"\Av1\.[0-9a-f]{64}\z")) { return ""; }
      var body = context.Request.Body?.As<Newtonsoft.Json.Linq.JObject>(preserveContent: true);
      if (body == null) { return ""; }
      var previous = body["previous_response_id"];
      if (previous != null && previous.Type != Newtonsoft.Json.Linq.JTokenType.Null
          && (previous.Type != Newtonsoft.Json.Linq.JTokenType.String
          || !System.Text.RegularExpressions.Regex.IsMatch((string)previous, @"\Aresp_[A-Za-z0-9_-]{1,128}\z"))) { return ""; }
      var conversation = body["conversation"];
      if (conversation != null && conversation.Type != Newtonsoft.Json.Linq.JTokenType.Null) { return ""; }
      var input = body["input"] as Newtonsoft.Json.Linq.JArray;
      if (input != null && input.OfType<Newtonsoft.Json.Linq.JObject>().Any(item => (string)item["type"] == "item_reference")) { return ""; }
      var metadataValue = body["metadata"];
      var metadata = metadataValue as Newtonsoft.Json.Linq.JObject;
      if (metadataValue != null && metadataValue.Type != Newtonsoft.Json.Linq.JTokenType.Null && metadata == null) { return ""; }
      if (metadata == null) { metadata = new Newtonsoft.Json.Linq.JObject(); }
      metadata.Remove("byok_owner_v1");
      if (metadata.Count > 15 || metadata.Properties().Any(property => property.Name.Length > 64
          || property.Value.Type != Newtonsoft.Json.Linq.JTokenType.String || ((string)property.Value).Length > 512)) { return ""; }
      metadata["byok_owner_v1"] = marker;
      body["metadata"] = metadata;
      return body.ToString(Newtonsoft.Json.Formatting.None);
    } catch { return ""; }
  }
